// Parse the incoming CSV and normalise identifiers with the SAME rules
// as the Task 1 pipeline (src/pipeline/normalize.py):
//   email: trim + lowercase, must look like an address
//   phone: strip non-digits, peel 091/91/0 prefixes, must be 10 digits
//          starting 6-9, stored as +91 E.164
// Invalid values become null rather than guesses - identical policy to
// the pipeline: an identifier we cannot trust must not be used to match.

const body = $input.first().json.body ?? $input.first().json;
let csv = null;
if (typeof body === 'string') csv = body;
else if (body && typeof body.csv === 'string') csv = body.csv;
if (!csv || !csv.trim()) {
  throw new Error('No CSV found. POST JSON {"csv": "name,email,phone\\n..."} or a form field named csv.');
}

// Minimal RFC-4180 parser: quoted fields, escaped quotes, CRLF or LF.
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else { field += c; }
    } else if (c === '"') { inQuotes = true; }
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') {
      row.push(field.replace(/\r$/, '')); field = '';
      rows.push(row); row = [];
    } else { field += c; }
  }
  if (field !== '' || row.length) { row.push(field.replace(/\r$/, '')); rows.push(row); }
  return rows.filter(r => r.some(v => v.trim() !== ''));
}

const EMAIL_RE = /^[^@\s,]+@[^@\s,]+\.[^@\s,]+$/;
function normEmail(raw) {
  if (!raw || !String(raw).trim()) return null;
  const v = String(raw).trim().toLowerCase();
  return EMAIL_RE.test(v) ? v : null;
}
function normPhone(raw) {
  if (!raw || !String(raw).trim()) return null;
  let d = String(raw).replace(/\D/g, '');
  if (d.length === 13 && d.startsWith('091')) d = d.slice(3);
  else if (d.length === 12 && d.startsWith('91')) d = d.slice(2);
  else if (d.length === 11 && d.startsWith('0')) d = d.slice(1);
  return /^[6-9]\d{9}$/.test(d) ? '+91' + d : null;
}

const rows = parseCsv(csv);
if (!rows.length) throw new Error('CSV is empty.');

const header = rows[0].map(h => h.trim().toLowerCase());
const nameIdx = header.indexOf('name');
const emailIdx = header.indexOf('email');
const phoneIdx = header.indexOf('phone');
if (nameIdx === -1 && emailIdx === -1 && phoneIdx === -1) {
  throw new Error('Header must contain at least one of: name, email, phone. Got: ' + header.join(','));
}

return rows.slice(1).map((r, i) => {
  const emailRaw = emailIdx >= 0 ? (r[emailIdx] ?? '') : '';
  const phoneRaw = phoneIdx >= 0 ? (r[phoneIdx] ?? '') : '';
  return { json: {
    row_number: i + 1,
    // commas stripped: n8n query-replacement splits parameters on commas
    name: nameIdx >= 0 ? (r[nameIdx] ?? '').trim().replace(/,/g, ' ') : '',
    email_raw: emailRaw,
    phone_raw: phoneRaw,
    email_norm: normEmail(emailRaw),
    phone_e164: normPhone(phoneRaw),
  }};
});

const j = $json;
const out = {
  status: 'DUPLICATE',
  row: j.row_number,
  incoming: { name: j.incoming_name, email: j.incoming_email, phone: j.incoming_phone },
  matched_person: { id: j.person_id, name: j.matched_name, city: j.matched_city },
  match: { method: j.method, confidence: Number(j.confidence), evidence: j.evidence },
  action: 'not inserted - flagged for review',
};
if (Number(j.candidate_people) > 1) {
  out.warning = 'email and phone point at DIFFERENT existing people - needs human review';
}
return { json: out };

const j = $json;
const hadIdentifier = !!(j.incoming_email || j.incoming_phone);
return { json: {
  status: hadIdentifier ? 'NEW' : 'UNCHECKABLE',
  row: j.row_number,
  incoming: { name: j.incoming_name, email: j.incoming_email, phone: j.incoming_phone },
  message: hadIdentifier
    ? 'no existing person matched either identifier'
    : 'row carried no valid email or phone - identity cannot be checked',
  action: hadIdentifier
    ? 'safe to continue as a new record (this workflow does not create one)'
    : 'rejected for identity purposes - fix the identifiers and resubmit',
}};

const results = $input.all().map(i => i.json)
  .sort((a, b) => (a.row || 0) - (b.row || 0));
const duplicates = results.filter(r => r.status === 'DUPLICATE').length;
const fresh = results.filter(r => r.status === 'NEW').length;
const uncheckable = results.filter(r => r.status === 'UNCHECKABLE').length;
return [{ json: {
  summary: {
    rows_checked: results.length,
    duplicates,
    new_records: fresh,
    uncheckable,
  },
  results,
}}];
